#include <stdio.h>
#include <stdlib.h>

#define MAXN 100000

typedef struct {
    long long key;
    int priority;
    int left;
    int right;
    int count;
    int size;
} Node;

static Node tree[MAXN + 1];
static int nodes = 0;
static unsigned int rng_state = 2463534242u;

static unsigned int next_random(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

static int subtree_size(int node) {
    return node == 0 ? 0 : tree[node].size;
}

static void update_size(int node) {
    tree[node].size = tree[node].count
                    + subtree_size(tree[node].left)
                    + subtree_size(tree[node].right);
}

static int rotate_right(int root) {
    int child = tree[root].left;
    tree[root].left = tree[child].right;
    tree[child].right = root;
    update_size(root);
    update_size(child);
    return child;
}

static int rotate_left(int root) {
    int child = tree[root].right;
    tree[root].right = tree[child].left;
    tree[child].left = root;
    update_size(root);
    update_size(child);
    return child;
}

static int insert(int root, long long key) {
    if (root == 0) {
        int node = ++nodes;
        tree[node].key = key;
        tree[node].priority = (int)next_random();
        tree[node].count = 1;
        tree[node].size = 1;
        return node;
    }

    if (key == tree[root].key) {
        tree[root].count++;
    } else if (key < tree[root].key) {
        tree[root].left = insert(tree[root].left, key);
        if ((unsigned int)tree[tree[root].left].priority >
            (unsigned int)tree[root].priority) {
            root = rotate_right(root);
        }
    } else {
        tree[root].right = insert(tree[root].right, key);
        if ((unsigned int)tree[tree[root].right].priority >
            (unsigned int)tree[root].priority) {
            root = rotate_left(root);
        }
    }

    update_size(root);
    return root;
}

static int count_at_most(int root, long long key) {
    int result = 0;

    while (root != 0) {
        if (key < tree[root].key) {
            root = tree[root].left;
        } else {
            result += subtree_size(tree[root].left) + tree[root].count;
            root = tree[root].right;
        }
    }

    return result;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int root = 0;
    int previous_penalty = 0;

    for (int i = 0; i < n; i++) {
        long long x, y;
        scanf("%lld %lld", &x, &y);

        x += previous_penalty;
        y += previous_penalty;

        long long distance_squared = x * x + y * y;
        int penalty = count_at_most(root, distance_squared);

        printf("%d\n", penalty);
        root = insert(root, distance_squared);
        previous_penalty = penalty;
    }

    return 0;
}
